var t=`0274-struklji`;var n=`world-0274`;var o=`SI`;var a=`southern-europe`;var r=4;var l=61;var s={en:`Štruklji`,ua:`Штруклі`};var g={en:`A traditional Slovenia dish made with all-purpose flour, chicken egg, whole cow milk, farmer cheese. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Словенія. Основні інгредієнти: пшеничне борошно універсальне, куряче яйце, цільне коров'яче молоко, домашній кисломолочний сир. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`all-purpose-flour`,350,`g`],[`chicken-egg`,2,`pcs`],[`whole-cow-milk`,160,`ml`],[`table-salt`,3,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:6,i:[[`farmer-cheese`,330,`g`],[`sour-cream`,80,`g`],[`white-granulated-sugar`,70,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:15,i:[]},{en:`Arrange the prepared food over gently boiling water or in a covered steamer. Steam for about 28 minutes until fully cooked; discard any bivalves that stay closed after cooking.`,ua:`Розмістіть підготовлені продукти над киплячою водою або в закритій пароварці. Готуйте на парі приблизно 28 хвилин до готовності; двостулкових молюсків, які не розкрилися, викиньте.`,t:[`steaming`],m:28,i:[[`water`,600,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`unsalted-butter`,55,`g`]]}];var u={slug:t,id:n,country:`SI`,region:a,servings:4,minutes:61,title:s,text:g,steps:d};export{o as country,u as default,n as id,l as minutes,a as region,r as servings,t as slug,d as steps,g as text,s as title};